-- Tenant-owned payroll items and immutable bulk salary preview intents.
CREATE TABLE ty_pay_setup_item(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),
 code text NOT NULL UNIQUE,display_code text NOT NULL,name text NOT NULL,system text NOT NULL CHECK(system IN('COMMON','CN_PAYROLL','HK_PAYROLL')),
 category text NOT NULL CHECK(category IN('cash_earnings','personal_deduction','employer_cost')),unit text NOT NULL CHECK(unit='currency_amount'),
 status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','approved')),revision integer NOT NULL DEFAULT 1 CHECK(revision=1),
 evidence_ref text NOT NULL CHECK(length(btrim(evidence_ref))>=4),created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),approved_at timestamptz,
 UNIQUE(group_id,display_code),CHECK(code='CUST_G'||group_id::text||'_'||display_code),CHECK(length(code)<=64),CHECK(display_code~'^[A-Z][A-Z0-9_]{1,39}$'),
 CHECK(status<>'approved'OR(approved_by IS NOT NULL AND approved_by<>created_by AND approved_at IS NOT NULL))
);
CREATE TABLE ty_pay_setup_preview(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),actor_id bigint NOT NULL REFERENCES sys_account(id),
 token text NOT NULL,request jsonb NOT NULL,plan jsonb NOT NULL,plan_hash text NOT NULL,
 status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','saved')),result jsonb,created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE FUNCTION fn_ty_pay_setup_immutable()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='工资项目和批量定薪意图保留历史，不可删除';END IF;
 IF TG_TABLE_NAME='ty_pay_setup_item'THEN
  IF OLD.status<>'draft'OR NEW.status<>'approved'OR(to_jsonb(NEW)-ARRAY['status','approved_by','approved_at'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['status','approved_by','approved_at'])THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='工资项目发布后冻结，草稿只能独立发布';END IF;
  IF public.fn_ty_hr_same_human(NEW.created_by,NEW.approved_by)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='工资项目须另一自然人独立发布';END IF;
 ELSE
  IF OLD.status<>'draft'OR NEW.status<>'saved'OR(to_jsonb(NEW)-ARRAY['status','result'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['status','result'])THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='定薪预检不可篡改或重复生效';END IF;
 END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_pay_setup_item_immutable BEFORE UPDATE OR DELETE ON ty_pay_setup_item FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_setup_immutable();
CREATE TRIGGER ty_pay_setup_preview_immutable BEFORE UPDATE OR DELETE ON ty_pay_setup_preview FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_setup_immutable();
-- Only structural catalogue references are checked; audit text is not a reference.
CREATE FUNCTION fn_ty_pay_setup_tenant_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE j jsonb:=to_jsonb(NEW);g bigint;codes text[]:='{}';c text;v jsonb;k text;BEGIN
 g:=nullif(j->>'group_id','')::bigint;
 IF TG_TABLE_NAME='ty_pay_config'THEN
  FOR v IN SELECT value FROM jsonb_array_elements(coalesce(j->'data'->'rules','[]'))LOOP codes:=array_append(codes,v->>'code');END LOOP;
  FOR v IN SELECT value FROM jsonb_each(coalesce(j->'data'->'source_treatments','{}'))LOOP FOR k IN SELECT jsonb_object_keys(v)LOOP codes:=array_append(codes,k);END LOOP;END LOOP;
  IF j->'data'->>'setup_rulebook_id'IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_pay_config b WHERE b.id=(j->'data'->>'setup_rulebook_id')::bigint AND b.group_id=g AND b.company_id=(j->>'company_id')::bigint AND b.system=j->>'system'AND b.kind='rulebook'AND b.status='approved')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='工资档案须关联同公司同体系已核方案';END IF;
 ELSIF TG_TABLE_NAME='ty_pay_stat_config'THEN
  FOR k IN SELECT jsonb_object_keys(coalesce(j->'data'->'scope_by_item','{}'))LOOP codes:=array_append(codes,k);END LOOP;
  FOR v IN SELECT value FROM jsonb_array_elements(coalesce(j->'data'->'deductible_codes','[]'))LOOP codes:=array_append(codes,v#>>'{}');END LOOP;
 ELSIF TG_TABLE_NAME='ty_hr_contract_term'THEN codes:=array_append(codes,j->>'payroll_item_code');SELECT group_id INTO g FROM public.ty_hr_contract WHERE id=NEW.contract_id;
 ELSIF TG_TABLE_NAME='ty_pay_item'THEN codes:=array_append(codes,j->>'code');SELECT group_id INTO g FROM public.ty_pay_row WHERE id=NEW.row_id;
 ELSIF TG_TABLE_NAME='ty_wf_bill_line'THEN codes:=array_append(codes,j->>'item_code');SELECT r.group_id INTO g FROM public.ty_wf_bill_version v JOIN public.ty_wf_bill_root r ON r.id=v.root_id WHERE v.id=NEW.version_id;
 ELSIF TG_TABLE_NAME='ty_lr_rule'THEN codes:=array_append(codes,j->'config'->>'item_code');
 ELSE codes:=array_append(codes,j->>'item_code');END IF;
 FOREACH c IN ARRAY codes LOOP
  IF c LIKE'CUST_G%'AND NOT EXISTS(SELECT 1 FROM public.ty_pay_setup_item WHERE code=c AND group_id=g AND status='approved')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='自定义工资项目未发布或不属于当前集团';END IF;
 END LOOP;RETURN NEW;
END;$$;
DO $$DECLARE name text;BEGIN
 FOREACH name IN ARRAY ARRAY['ty_pay_config','ty_pay_stat_config','ty_hr_contract_term','ty_pay_item','ty_wf_bill_line','ty_cp_resolution','ty_pr_award_parent','ty_lr_award_parent','ty_lr_rule']LOOP
  EXECUTE format('CREATE TRIGGER zz_pay_setup_tenant BEFORE INSERT OR UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.fn_ty_pay_setup_tenant_guard()',name);
 END LOOP;
END;$$;
CREATE FUNCTION fn_ty_pay_setup_metadata(p_group bigint,p_id bigint,p_code text,p_category text)RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=''AS $$
 SELECT jsonb_build_object('custom_group_id',p_group::text,'custom_item_id',p_id::text,'key','tyhr.custom.'||p_code,'exclusion_group',null,'mandatory_when_applicable',false,'optional_user_toggle',true,'creates_additional_payable',p_category<>'personal_deduction','employee_cash_wage_effect',CASE p_category WHEN 'cash_earnings'THEN'increase_gross'WHEN'personal_deduction'THEN'decrease_net'ELSE'none'END,'cost_additive',p_category IN('cash_earnings','employer_cost'),'cash_component_nature',CASE WHEN p_category='cash_earnings'THEN'allowance_or_incentive'ELSE p_category END,'configuration_requirements',jsonb_build_array('工资方案公式及有效工资档案','独立复核计入与排除标签'));
$$;
CREATE FUNCTION fn_ty_pay_setup_catalog_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$BEGIN
 IF NEW.code LIKE'CUST_G%'AND NOT EXISTS(SELECT 1 FROM public.ty_pay_setup_item s WHERE s.code=NEW.code AND s.status='approved'AND s.name=NEW.name AND s.system=NEW.system AND s.category=NEW.category AND s.unit=NEW.unit AND NEW.output_ledger=CASE s.category WHEN'cash_earnings'THEN'employee_gross_wage'WHEN'personal_deduction'THEN'employee_deduction'ELSE'employer_cost'END AND NEW.metadata=public.fn_ty_pay_setup_metadata(s.group_id,s.id,s.code,s.category))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='自定义工资项目只能按已发布定义和固定账册性质登记';END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_pay_setup_catalog_guard BEFORE INSERT ON ty_pay_item_catalog FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_setup_catalog_guard();
